// ---- one-parameter transport for Postgres writes ----------------------------
// The Postgres node splits its Query Parameters string on commas AFTER resolving
// expressions (observed live 2026-09-08), so a comma in an address shifts every
// bind parameter. Base64 has no commas: ship one encoded JSON document and unpack
// it in SQL with convert_from(decode($1,'base64'),'UTF8')::jsonb.
function toB64(str) {
  if (typeof Buffer !== 'undefined') return Buffer.from(str, 'utf8').toString('base64');
  return btoa(unescape(encodeURIComponent(str)));
}

