  appt_date: ctx.apptDate, appt_time: ctx.apptTime, cal_uid: uid, sms_consent: !!ctx.smsConsent,
};
return [{ json: { ...ctx, calBookingUid: uid, calOk: !!uid, jobPayloadB64: toB64(JSON.stringify(jobPayload)) } }];

