}


// Reached from two places: Request Valid? (false) with the Parse output, or
// Booking Confirmed? (false) with the Merge output (which carries eventTypeId).
const ctx = $input.first().json || {};
if (!ctx.valid) {
  return vapiResult(ctx.toolCallId,
    'I am missing something I need to book that — the name, the address, or a clear date and time. ' +
    'Ask for whatever is missing, then call this again. Nothing has been booked.');
}
if (ctx.eventTypeId == null) {
  // Cal.com itself was unreachable — do NOT send the model back into check_availability.
  return vapiResult(ctx.toolCallId,
    'The calendar could not be reached, so nothing was booked. Do not retry. Take their name, number and the time ' +
    'they wanted, and call capture_lead with reason other so Anthony can confirm it personally.');
}
return vapiResult(ctx.toolCallId,
  'That slot is no longer available. Apologise briefly, call check_availability again, and offer a different time. ' +
  'Nothing has been booked and no record was created.');
